using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Threading;
using DogSC.Windows;

namespace DogSC.Replica {
 static class ExportCorrectnessTests {
  static void Check(bool value,string message){if(!value)throw new Exception(message);}
  static double Frequency(string source,double at,string output){StudioMedia.Run("-v error -y -ss "+Media.N(at)+" -t 0.2 -i "+Media.Q(source)+" -vn -ac 1 -ar 48000 -c:a pcm_s16le -f s16le "+Media.Q(output),CancellationToken.None);var data=File.ReadAllBytes(output);int crossings=0;short prior=0;for(int i=0;i+1<data.Length;i+=2){short sample=BitConverter.ToInt16(data,i);if(prior<=0&&sample>0)crossings++;prior=sample;}return crossings/(data.Length/2.0/48000);}
  static void AssertScene(string video,double at,bool red){using(var data=new MemoryStream(StudioMedia.Frame(video,at,320)))using(var image=new Bitmap(data)){Color pixel=image.GetPixel(160,90);Check(red?pixel.R>180&&pixel.B<90:pixel.B>180&&pixel.R<90,"Video trim or order incorrect at "+at+": "+pixel);}}
  public static void Run(){string root=Path.Combine(Media.Root,"bin","export-correctness",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string log=Path.Combine(Media.Root,"bin","export-correctness-results.txt");try{string source=Path.Combine(root,"source.mp4");string filters="[0:v][1:a][2:v][3:a]concat=n=2:v=1:a=1[v][a]";StudioMedia.Run("-v error -y -f lavfi -i color=c=red:s=320x180:r=30:d=1 -f lavfi -i sine=frequency=440:sample_rate=48000:duration=1 -f lavfi -i color=c=blue:s=320x180:r=30:d=1 -f lavfi -i sine=frequency=880:sample_rate=48000:duration=1 -filter_complex "+Media.Q(filters)+" -map [v] -map [a] -c:v libx264 -preset ultrafast -c:a aac "+Media.Q(source),CancellationToken.None);var doc=StudioMedia.Import(source);doc.Style.Frame="none";doc.Style.Padding=0;doc.Style.Radius=0;doc.Style.Shadow=0;doc.Style.AutoZoom=false;doc.Zooms.Clear();doc.Cuts=new List<Cut>{new Cut {Start=.5,End=1.5}};string direct=Path.Combine(root,"direct.mp4");StudioRenderer.Export(doc,direct,180,30,(x,s)=>{},CancellationToken.None);var imported=StudioMedia.Import(direct);Check(imported.Audio&&Math.Abs(imported.Duration-1)<.1,"Direct trim duration/audio");AssertScene(direct,.2,true);AssertScene(direct,.8,false);double a=Frequency(direct,.15,Path.Combine(root,"a.pcm")),b=Frequency(direct,.65,Path.Combine(root,"b.pcm"));Check(Math.Abs(a-440)<35&&Math.Abs(b-880)<35,"Direct trim audio/video alignment: "+a+" / "+b);
   doc.Cuts=new List<Cut>{new Cut {Start=1,End=1.8},new Cut {Start=0,End=.4,Speed=.5}};string edited=Path.Combine(root,"edited.mp4");StudioRenderer.Export(doc,edited,180,30,(x,s)=>{},CancellationToken.None);imported=StudioMedia.Import(edited);Check(imported.Audio&&Math.Abs(imported.Duration-1.6)<.15,"Multi-cut duration/audio");AssertScene(edited,.2,false);AssertScene(edited,1.2,true);a=Frequency(edited,.15,Path.Combine(root,"c.pcm"));Check(Math.Abs(a-880)<35,"Reordered audio did not follow video: "+a);
   string cancelled=Path.Combine(root,"cancelled.mp4");using(var cts=new CancellationTokenSource()){bool caught=false;try{StudioRenderer.Export(doc,cancelled,180,30,(x,s)=>{if(x>=.1)cts.Cancel();},cts.Token);}catch(OperationCanceledException){caught=true;}Check(caught&&!File.Exists(cancelled)&&Directory.GetDirectories(root,".dogsc-*").Length==0,"Cancellation left output or temporary files");}File.WriteAllText(log,"PASS: direct trimmed export preserves scene and matching audio; reordered/slow cuts preserve timing; cancellation leaves no partial output.\nArtifacts: "+root+"\n");}catch(Exception ex){File.WriteAllText(log,"FAIL\n"+ex+"\nArtifacts: "+root);Environment.ExitCode=1;}}
 }
}
